import 'package:flutter_test/flutter_test.dart';
import 'package:hustle_mobile/features/analysis/domain/analysis.dart';
void main(){test('tam analiz yanıtını ayrıştırır',(){final result=Analysis.fromJson({'source_service':'hustle-analytics','source_event_id':'id','symbol':'BTCUSDT','exchange':'BINANCE','timeframe':'1h','action':'SAFE_BUY','confidence':.8,'price':64000,'signal_time':'2026-01-01T00:00:00Z','reasons':['RSI düşük'],'indicators':{'rsi_14':29,'macd':1}});expect(result.action,SignalAction.safeBuy);expect(result.indicators.rsi14,29);});test('eksik alanlar ve bilinmeyen action güvenlidir',(){final result=Analysis.fromJson({'symbol':'ETHUSDT','action':'NEW_ACTION','confidence':'bad'});expect(result.action,SignalAction.unknown);expect(result.confidence,0);expect(result.reasons,isEmpty);});}
